import csv
import json
import sys


def convert(value):
    if value == "":
        return None
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        return value


with open(sys.argv[1], newline="", encoding="utf-8") as handle:
    rows = [{key: convert(item) for key, item in row.items()} for row in csv.DictReader(handle)]
with open(sys.argv[2], "w", encoding="utf-8") as handle:
    json.dump(rows, handle)

